// Records the Chrome control for tests/screenshot_image_formats.rs (turbo-surf#30): screenshots
// tests/fixtures/screenshot_image_formats.html (generated by turbo-surf-render's
// tests/fixture-gen/make-image-format-cases.py) in Chrome and samples each image's pixels
// (its centre and an inset corner) into tests/fixtures/screenshot_image_formats_chrome156.json.
// Regenerate (Chrome for Testing):
//   TURBO_SURF_CHROME_PATH=".../Google Chrome for Testing" \
//     node rust/crates/turbo-surf-mcp/tests/fixture-gen/screenshot-image-formats-chrome.mjs
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { inflateSync } from "node:zlib";
import { chromium } from "playwright";

const here = (path) => new URL(path, import.meta.url);
const sha256 = (bytes) => createHash("sha256").update(bytes).digest("hex");
const page = readFileSync(here("../fixtures/screenshot_image_formats.html"), "utf8");
const executablePath = process.env.TURBO_SURF_CHROME_PATH;
if (!executablePath) throw new Error("set TURBO_SURF_CHROME_PATH to the Chrome binary");
const viewport = { width: 520, height: 90 };

// Decode an 8-bit, non-interlaced RGB/RGBA PNG (what Chrome's screenshots are) to RGBA rows.
function decodePng(png) {
  let offset = 8;
  let width = 0;
  let channels = 4;
  const data = [];
  while (offset < png.length) {
    const length = png.readUInt32BE(offset);
    const kind = png.toString("latin1", offset + 4, offset + 8);
    const body = png.subarray(offset + 8, offset + 8 + length);
    if (kind === "IHDR") {
      width = body.readUInt32BE(0);
      if (body[8] !== 8 || body[12] !== 0) throw new Error("unsupported PNG");
      channels = { 2: 3, 6: 4 }[body[9]];
    } else if (kind === "IDAT") data.push(body);
    offset += 12 + length;
  }
  const raw = inflateSync(Buffer.concat(data));
  const stride = width * channels;
  const rows = [];
  let previous = Buffer.alloc(stride);
  for (let at = 0; at < raw.length; at += stride + 1) {
    const filter = raw[at];
    const row = Buffer.from(raw.subarray(at + 1, at + 1 + stride));
    for (let i = 0; i < stride; i++) {
      const left = i >= channels ? row[i - channels] : 0;
      const up = previous[i];
      const corner = i >= channels ? previous[i - channels] : 0;
      const paeth = () => {
        const p = left + up - corner;
        const [a, b, c] = [Math.abs(p - left), Math.abs(p - up), Math.abs(p - corner)];
        return a <= b && a <= c ? left : b <= c ? up : corner;
      };
      const add = [0, left, up, (left + up) >> 1, paeth()][filter];
      row[i] = (row[i] + add) & 255;
    }
    rows.push(row);
    previous = row;
  }
  return (x, y) => {
    const row = rows[y];
    const i = x * channels;
    return [row[i], row[i + 1], row[i + 2], channels === 4 ? row[i + 3] : 255];
  };
}

const browser = await chromium.launch({ executablePath, headless: true });
try {
  const errors = [];
  const tab = await browser.newPage({ viewport, deviceScaleFactor: 1 });
  tab.on("pageerror", (error) => errors.push(String(error)));
  await tab.route("https://screenshot.test/", (route) =>
    route.fulfill({ contentType: "text/html", body: page }),
  );
  await tab.goto("https://screenshot.test/", { waitUntil: "load" });
  const boxes = await tab.evaluate(() =>
    Array.from(document.images, (img) => {
      const r = img.getBoundingClientRect();
      return { id: img.dataset.id, x: r.x, y: r.y, width: r.width, height: r.height };
    }),
  );
  const pixel = decodePng(await tab.screenshot({ type: "png" }));
  const samples = boxes.flatMap((box) =>
    [
      [box.x + Math.floor(box.width / 2), box.y + Math.floor(box.height / 2)],
      [box.x + 2, box.y + 2],
    ].map(([x, y]) => ({ id: box.id, x, y, rgba: pixel(x, y) })),
  );
  const control = {
    browser: `Chrome/${browser.version()}`,
    pageSha256: sha256(page),
    collectorSha256: sha256(readFileSync(new URL(import.meta.url))),
    viewport: [viewport.width, viewport.height],
    errors,
    boxes,
    samples,
  };
  writeFileSync(
    here("../fixtures/screenshot_image_formats_chrome156.json"),
    `${JSON.stringify(control, null, 2)}\n`,
  );
} finally {
  await browser.close();
}
